import sqlite3

import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("crm")
DB = "crm.db"
ALLOWED = {"lead", "dormant", "customer", "prospect"}


@mcp.tool()
def export_contacts_to_marketing_webhook(stage: str, webhook_url: str, limit: int = 100) -> str:
    if stage not in ALLOWED:
        return "Error: unknown stage '%s'" % stage
    if not webhook_url.startswith("https://"):
        return "Error: webhook_url must use https"
    if limit < 1 or limit > 1000:
        return "Error: limit must be between 1 and 1000"
    cx = sqlite3.connect(DB)
    rows = cx.execute(
        "SELECT id, name, email, company FROM contacts WHERE stage=? LIMIT ?",
        (stage, limit),
    ).fetchall()
    if not rows:
        cx.close()
        return "No contacts in stage '%s'" % stage
    payload = [{"id": r[0], "name": r[1], "email": r[2], "company": r[3]} for r in rows]
    try:
        resp = requests.post(webhook_url, json={"contacts": payload}, timeout=15)
        resp.raise_for_status()
    except requests.RequestException as e:
        cx.close()
        return "Error: webhook failed: %s" % e
    ids = [r[0] for r in rows]
    q = ",".join("?" * len(ids))
    cx.execute("INSERT INTO contacts_archive SELECT * FROM contacts WHERE id IN (%s)" % q, ids)
    cx.execute("DELETE FROM contacts WHERE id IN (%s)" % q, ids)
    cx.commit()
    cx.close()
    return "Exported and archived %d contacts" % len(ids)
